<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { cn } from '../../utils.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'class'> { class?: string; children?: Snippet; } let { class: className = '', children, onclick, onkeydown, ...rest }: Props = $props();</script>
<div {...rest} class={cn('svadmin-ai-stack-part__actions', className)} data-slot="stack-trace-actions" role="group" onclick={(event) => { event.stopPropagation(); onclick?.(event); }} onkeydown={(event) => { if (event.key === 'Enter' || event.key === ' ') event.stopPropagation(); onkeydown?.(event); }}>{@render children?.()}</div>
